import{_ as a,o,c as s,ag as r}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Framework personalizado","description":"","frontmatter":{},"headers":[],"relativePath":"es/bridge/custom.md","filePath":"es/bridge/custom.md"}'),i={name:"es/bridge/custom.md"};function t(l,e,d,c,n,u){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="framework-personalizado" tabindex="-1">Framework personalizado <a class="header-anchor" href="#framework-personalizado" aria-label="Permalink to &quot;Framework personalizado&quot;">​</a></h1><p>¿Usas un framework que el bridge no admite, o uno muy modificado? Conéctalo tú mismo: todos los scripts Nayretis lo usarán.</p><p>El archivo <code>nay_lib/bridge/custom.lua</code> se entrega legible, fuera del escrow de Cfx. Contiene dos tablas, una para el servidor y otra para el cliente, con todas las funciones que necesitan los scripts: leer el jugador y su trabajo, dinero, objetos, notificaciones. Cada función está documentada en el archivo con sus argumentos y los valores que debe devolver.</p><h2 id="pasos" tabindex="-1">Pasos <a class="header-anchor" href="#pasos" aria-label="Permalink to &quot;Pasos&quot;">​</a></h2><ol><li><p>Abre <code>nay_lib/bridge/custom.lua</code> e implementa todas las funciones de las tablas del servidor y del cliente con los exports o eventos de tu framework.</p></li><li><p>En <code>server.cfg</code>, fuerza el adaptador personalizado:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;custom&quot;</span></span></code></pre></div></li><li><p>Reinicia el servidor. El archivo lo lee cada recurso que usa <code>nay_lib</code>, así que reinícialos todos después de cualquier cambio.</p></li></ol><p>La consola lo confirma al arrancar: <code>Bridge ready: framework=custom ...</code>.</p><h2 id="lo-que-el-bridge-ya-hace-por-ti" tabindex="-1">Lo que el bridge ya hace por ti <a class="header-anchor" href="#lo-que-el-bridge-ya-hace-por-ti" aria-label="Permalink to &quot;Lo que el bridge ya hace por ti&quot;">​</a></h2><p>Solo tienes que hablar con tu framework. El propio bridge:</p><ul><li>valida los importes y las cuentas (<code>cash</code> y <code>bank</code>, importes enteros positivos);</li><li>comprueba el saldo antes de quitar dinero y la cantidad antes de quitar objetos;</li><li>avisa a los scripts cuando un jugador se desconecta.</li></ul><p>¿Necesitas ayuda? Abre un post en <code>#support</code> en el <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Discord de Nayretis</a>.</p>',10)])])}const b=a(i,[["render",t]]);export{m as __pageData,b as default};
